$path = Join-Path $PSScriptRoot '..\admin-panel\app\islamic-lifestyle\page.tsx'
$content = [IO.File]::ReadAllText((Resolve-Path $path), [Text.Encoding]::UTF8)
$old = '<div className="languageControls"><input aria-label="Search languages" value={languageQuery} onChange={e=>setLanguageQuery(e.target.value)} placeholder="Search Bengali, Arabic, Spanish..."/><select aria-label="Content language" value={language} onChange={e=>selectLanguage(e.target.value)}><option value="en">English (Base)</option>{languages.filter(x=>x.code!=="en"&&(!languageQuery.trim()||(`${x.label} ${x.code}`).toLowerCase().includes(languageQuery.trim().toLowerCase()))).map(x=><option key={x.code} value={x.code}>{x.label} ({x.code.toUpperCase()}){form.id&&items.find(item=>item.id===form.id)?.translations?.[x.code]?" - Saved":""}</option>)}</select></div>'
$new = '<div className="languageControls single"><label><span>Select content language</span><select aria-label="Select content language" value={language} onChange={e=>selectLanguage(e.target.value)}><option value="en">English (Base)</option>{languages.filter(x=>x.code!=="en").map(x=><option key={x.code} value={x.code}>{x.label} ({x.code.toUpperCase()}){form.id&&items.find(item=>item.id===form.id)?.translations?.[x.code]?" - Saved":""}</option>)}</select><small>Click to choose from all 195 languages. You can type the first letters while the list is open.</small></label></div>'
if (-not $content.Contains($old)) { throw 'Language controls anchor not found' }
$content = $content.Replace($old,$new)
$content = $content.Replace('.languageControls input,.languageControls select{background:#fff}', '.languageControls input,.languageControls select{background:#fff}.languageControls.single{grid-template-columns:1fr}.languageControls.single label span{display:block;margin-bottom:6px;font-size:11px;font-weight:800;color:#275342}.languageControls.single label small{display:block;margin-top:6px;color:#718078;font-size:9px}')
[IO.File]::WriteAllText((Resolve-Path $path), $content, [Text.UTF8Encoding]::new($false))
